#include <bits/stdc++.h>
using namespace std;
vector<int> get(const string&s,const string&name){auto a=s.find("\""+name+"\":[");if(a==string::npos)abort();a+=name.size()+4;auto b=s.find(']',a);string z=s.substr(a,b-a);vector<int>v;string t;istringstream ss(z);while(getline(ss,t,','))v.push_back(stoi(t));return v;}
int main(int argc,char**argv){string file=argc>1?argv[1]:"E064_quotient_representatives.jsonl";ifstream in(file);int count=0,excluded=0;long long choices=0,zm=0;vector<pair<int,int>> ex;string line;while(getline(in,line)){auto f=get(line,"B_col0"),g=get(line,"C_col0");assert(f.size()==10&&g.size()==10);int degree[1000]{};bool covered[1000]{};bool AB[10][10]{},AC[10][10]{},BC[10][10]{};for(int r=0;r<10;r++)for(int c=0;c<10;c++){if(r!=0&&c!=0)continue;int a,b,d;if(r==0){a=b=d=c;}else{a=r;b=f[r];d=g[r];}int keys[]={r*10+c,100+r*10+a,200+c*10+a,300+r*10+b,400+c*10+b,500+r*10+d,600+c*10+d,700+a*10+b,800+a*10+d,900+b*10+d};for(int k:keys){assert(!covered[k]);covered[k]=true;}AB[a][b]=AC[a][d]=BC[b][d]=true;}
 for(int r=1;r<10;r++)for(int c=1;c<10;c++)for(int a=0;a<10;a++){if(a==r||a==c)continue;for(int b=0;b<10;b++){if(b==c||b==f[r]||AB[a][b])continue;for(int d=0;d<10;d++){if(d==c||d==g[r]||AC[a][d]||BC[b][d])continue;int keys[]={r*10+c,100+r*10+a,200+c*10+a,300+r*10+b,400+c*10+b,500+r*10+d,600+c*10+d,700+a*10+b,800+a*10+d,900+b*10+d};bool ok=true;for(int k:keys)if(covered[k])ok=false; if(!ok)abort();for(int k:keys)degree[k]++;choices++;}}}
 int z=0;for(int k=0;k<1000;k++)if(!covered[k]&&degree[k]==0)z++;if(z){excluded++;zm+=z;ex.push_back({count,z});}count++;}
 cout<<"{\"total_reps\":"<<count<<",\"support_unsat_reps\":"<<excluded<<",\"total_valid_candidates\":"<<choices<<",\"total_zero_resource_constraints\":"<<zm<<",\"excluded_ids\":[";for(int i=0;i<ex.size();i++){if(i)cout<<",";cout<<ex[i].first;}cout<<"]}\n";}